package com.visionerp.service; import com.visionerp.entity.User; import com.visionerp.repository.UserRepository; import com.visionerp.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder enc;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;}public String login(String email,String password){User u=users.findByEmail(email).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!u.enabled||!enc.matches(password,u.passwordHash))throw new IllegalArgumentException("Invalid credentials");return jwt.create(u.email,u.role.name());}}
